export type NotificationVariant = "info" | "success" | "error" | "warning";
interface NotifyOptionsBase {
    /** The Notification variant for styling of the notification. Defaults to "info" */
    variant?: NotificationVariant;
    durationMs?: number;
}
/** Options for customizing a notification. */
export interface NotifyOptions extends NotifyOptionsBase {
    /** A button to be displayed on the notification */
    button?: {
        /** The text of the button */
        text: string;
        /** Click handler when the button is pressed */
        onClick: () => void;
    };
    /** A function that is called when the notification disappears */
    onDisappear?: VoidFunction;
}
export interface NotifyOptionsData extends NotifyOptionsBase {
    buttonText?: string;
    notificationId: string;
}
/** A handle to an active notification, allowing it to be closed programmatically. */
export interface Notification {
    close: () => Promise<void>;
}
export type NotificationCloseReason = "timeoutReachedOrDismissed" | "actionButtonClicked";
/** Function signature for displaying a notification message. */
export type Notify = (message: string, options?: NotifyOptions) => Notification;
export {};
